mod sparse;mod scheduler;mod bridge;mod bqi;mod check;mod continuation;
#[cfg(test)]mod continuation_tests{
use super::*;use continuation::*;use sparse::{Owner,Charge,Polynomial};use std::time::{Instant,Duration};
#[derive(Default)]struct Ledger{work:u64,bytes:u64,checks:u64,stop:Option<u64>}
impl Owner for Ledger{fn reserve(&mut self,q:Charge)->Result<(),()>{self.work+=q.work;self.bytes+=q.bytes;Ok(())}fn check(&mut self)->Result<(),()>{self.checks+=1;if self.stop==Some(self.checks){Err(())}else{Ok(())}}}
fn limits()->Limits{Limits{partitions:64,work:100_000_000_000,bytes:100_000_000_000,search:scheduler::search::SearchLimits{nodes:32,native:scheduler::Limits{batch_rows:128,batch_ops:1024,batches:32,variables:256,generators:256,basis:256,tasks:1024,terms:256,proof:1024,degree:256,work:20_000_000,bytes:200_000_000}},audit:check::Limits{nodes:32,work:2_000_000_000,bytes:400_000_000,certificate:bridge::Limits{variables:256,generators:256,terms:256,degree:256,proof:1024,wire:65536,work:1_000_000_000,bytes:200_000_000},checker:bqi::Limits::software()}}}
fn deadline()->Instant{Instant::now()+Duration::from_secs(20)}
fn collect(n:u32,g:&[Polynomial],limits:Limits,o:&mut Ledger)->(Attempt,Vec<Vec<bool>>){let mut s=Session::new(n,g,limits,deadline(),o);let mut xs=Vec::new();loop{match s.next(){Ok(Outcome::CandidateRetained)=>{xs.push(s.candidate().unwrap().to_vec());if s.exclude(xs.len() as u64).is_err(){break}},_=>break}}(s.into_attempt(),xs)}
fn oracle(n:u32,g:&[Polynomial])->std::collections::BTreeSet<Vec<bool>>{(0..1u64<<n).map(|x|(0..n).map(|j|x>>j&1!=0).collect::<Vec<_>>()).filter(|x|g.iter().all(|p|!p.iter().fold(false,|s,t|s^t.iter().all(|v|x[*v as usize])))).collect()}
#[test]fn all_eight_models_unique_and_independent_coverage(){let g=vec![];let mut o=Ledger::default();let(a,x)=collect(3,&g,limits(),&mut o);assert_eq!(a.outcome,Outcome::RemainingBooleanModelsExhaustedUnderRecordedExclusions);assert_eq!(x.len(),8);assert_eq!(x.iter().cloned().collect::<std::collections::BTreeSet<_>>(),oracle(3,&g));assert_eq!(a.charge.work,o.work);assert_eq!(a.charge.bytes,o.bytes);let v=audit(3,&g,&a,limits(),deadline(),&mut Ledger::default());assert_eq!(v.result,Ok(()));assert_eq!(v.exclusions,8);}
#[test]fn tiny_ideals_match_independent_truth_tables(){let systems=vec![vec![vec![vec![],vec![0],vec![1]]],vec![vec![vec![0]],vec![vec![],vec![0]]],vec![vec![vec![0,1]],vec![vec![],vec![1],vec![2]]]];for g in systems{let(a,x)=collect(3,&g,limits(),&mut Ledger::default());assert_eq!(a.outcome,Outcome::RemainingBooleanModelsExhaustedUnderRecordedExclusions);assert_eq!(x.len(),x.iter().collect::<std::collections::BTreeSet<_>>().len());assert_eq!(x.into_iter().collect::<std::collections::BTreeSet<_>>(),oracle(3,&g));assert_eq!(audit(3,&g,&a,limits(),deadline(),&mut Ledger::default()).result,Ok(()));}}
#[test]fn retained_candidate_is_not_excluded_until_explicit_record(){let mut o=Ledger::default();let mut s=Session::new(2,&[],limits(),deadline(),&mut o);assert_eq!(s.next(),Ok(Outcome::CandidateRetained));let x=s.candidate().unwrap().to_vec();assert_eq!(s.next(),Ok(Outcome::CandidateRetained));assert_eq!(s.candidate(),Some(x.as_slice()));assert!(s.attempt.partitions[0].exclusion_record.is_none());s.exclude(91).unwrap();assert_eq!(s.attempt.partitions[0].exclusion_record,Some(91));assert_eq!(s.next(),Ok(Outcome::CandidateRetained));assert_ne!(s.candidate(),Some(x.as_slice()));}
#[test]fn coverage_rejects_source_split_exclusion_and_conditional_mutation(){for mode in 0..5{let g=vec![vec![vec![0]]];let(mut a,_)=collect(2,&g,limits(),&mut Ledger::default());match mode{0=>{a.partitions[0].children.pop();},1=>a.partitions[1].prefix[0]=!a.partitions[1].prefix[0],2=>a.partitions[0].exclusion_record=None,3=>a.partitions[1].equations[0]=vec![],_=>a.partitions[1].parent=None};assert!(audit(2,&g,&a,limits(),deadline(),&mut Ledger::default()).result.is_err());}}
#[test]fn global_cap_and_expired_deadline_are_sticky(){let mut l=limits();l.partitions=1;let mut o=Ledger::default();let mut s=Session::new(2,&[],l,deadline(),&mut o);assert_eq!(s.next(),Ok(Outcome::CandidateRetained));assert_eq!(s.exclude(1),Err(Failure::Cap));assert_eq!(s.next(),Err(Failure::Cap));assert_eq!(s.attempt.partitions.len(),1);assert_eq!(s.attempt.outcome,Outcome::Unknown);assert!(s.attempt.partitions[0].search.is_some());let mut o=Ledger::default();let mut s=Session::new(2,&[],limits(),Instant::now(),&mut o);assert_eq!(s.next(),Err(Failure::Deadline));assert!(s.attempt.partitions.is_empty());}
#[test]fn above128_candidate_and_bounded_partition_refusal(){let g=vec![vec![vec![],vec![129]]];let mut o=Ledger::default();let mut s=Session::new(130,&g,limits(),deadline(),&mut o);assert_eq!(s.next(),Ok(Outcome::CandidateRetained));assert!(s.candidate().unwrap()[129]);assert_eq!(s.exclude(1),Err(Failure::Cap));assert_eq!(s.attempt.partitions.len(),1);}
#[test]fn owner_refusal_sweep_retains_partial_partitions_and_exact_charges(){let mut base=Ledger::default();let(full,_)=collect(1,&[],limits(),&mut base);assert_eq!(full.outcome,Outcome::RemainingBooleanModelsExhaustedUnderRecordedExclusions);let mut saw_split=false;for stop in 1..=base.checks{let mut owner=Ledger{stop:Some(stop),..Default::default()};let(a,_)=collect(1,&[],limits(),&mut owner);assert_eq!(a.failure,Some(Failure::Owner),"{stop}");assert_eq!(a.outcome,Outcome::Unknown);assert_eq!(a.charge.work,owner.work);assert_eq!(a.charge.bytes,owner.bytes);saw_split|=a.partitions.iter().any(|p|p.status==Status::Splitting);}assert!(saw_split);}
#[test]fn callback_receives_same_owner_candidate_and_deadline_with_parent_charges(){
 let mut o=Ledger::default();let owner_address=(&mut o as *mut Ledger)as usize;let end=deadline();let mut s=Session::new(2,&[],limits(),end,&mut o);assert_eq!(s.next(),Ok(Outcome::CandidateRetained));let expected=s.candidate().unwrap().to_vec();
 let out=s.with_candidate_owner(|model,d,owner|{assert_eq!((owner as *mut Ledger)as usize,owner_address);assert_eq!(model,expected);assert_eq!(d,end);owner.reserve(Charge{work:17,bytes:23}).unwrap();(model.to_vec(),99)});assert_eq!(out.result,Ok(()));assert_eq!(out.value.unwrap().1,99);s.exclude(99).unwrap();let a=s.into_attempt();assert_eq!(o.work,a.charge.work+17);assert_eq!(o.bytes,a.charge.bytes+23);
}
#[test]fn callback_never_invoked_without_pending_candidate_or_after_terminal(){
 let mut o=Ledger::default();let mut s=Session::new(1,&[],limits(),deadline(),&mut o);let out=s.with_candidate_owner(|_,_,_|panic!("uninvoked"));assert_eq!(out.result,Err(Failure::State));assert!(out.value.is_none());
 let g=vec![vec![vec![]]];let mut o=Ledger::default();let mut s=Session::new(1,&g,limits(),deadline(),&mut o);assert_eq!(s.next(),Ok(Outcome::RemainingBooleanModelsExhaustedUnderRecordedExclusions));let out=s.with_candidate_owner(|_,_,_|panic!("uninvoked"));assert_eq!(out.result,Err(Failure::State));assert!(out.value.is_none());
}
#[test]fn callback_postcheck_refusal_retains_output_and_forbids_exclusion(){
 let mut o=Ledger::default();let mut s=Session::new(2,&[],limits(),deadline(),&mut o);assert_eq!(s.next(),Ok(Outcome::CandidateRetained));let out=s.with_candidate_owner(|model,_,owner|{owner.stop=Some(owner.checks+1);model.to_vec()});assert_eq!(out.result,Err(Failure::Owner));assert_eq!(out.value,Some(vec![false,false]));assert_eq!(s.exclude(7),Err(Failure::Owner));assert_eq!(s.next(),Err(Failure::Owner));assert_eq!(s.attempt.partitions[0].exclusion_record,None);assert_eq!(s.attempt.outcome,Outcome::Unknown);
}

}
